//#region src/shims/navigation-errors.d.ts
/**
 * Server-safe navigation control-flow errors and predicates.
 *
 * This module intentionally has no React or browser-runtime dependencies so
 * RSC, SSR, and the public next/navigation shim can share one implementation.
 */
export declare const HTTP_ERROR_FALLBACK_ERROR_CODE = "NEXT_HTTP_ERROR_FALLBACK";
export declare function isHTTPAccessFallbackError(error: unknown): boolean;
export declare function getAccessFallbackHTTPStatus(error: unknown): number;
export declare enum RedirectType {
  push = "push",
  replace = "replace"
}
/**
 * The omitted redirect type is resolved by the catch site: push for Server
 * Actions and replace for ordinary SSR/RSC rendering.
 */
export declare function redirect(url: string, type?: "replace" | "push" | RedirectType): never;
export declare function permanentRedirect(url: string, type?: "replace" | "push" | RedirectType): never;
export declare function notFound(): never;
export declare function forbidden(): never;
export declare function unauthorized(): never;
type RedirectErrorShape = Error & {
  digest: string;
};
/**
 * vinext accepts its three-part redirect digest and Next.js's five-part form.
 * This is deliberately only a cheap prefix gate because vinext permits an
 * empty redirect type; parseRedirectDigest is the authoritative validator.
 */
export declare function isRedirectError(error: unknown): error is RedirectErrorShape;
export declare function decodeRedirectError(digest: string): {
  url: string;
  type: "push" | "replace";
} | null;
export declare function isNextRouterError(error: unknown): boolean;
export declare class BailoutToCSRError extends Error {
  readonly digest = "BAILOUT_TO_CLIENT_SIDE_RENDERING";
  readonly reason: string;
  constructor(reason: string);
}
export declare function isBailoutToCSRError(error: unknown): error is BailoutToCSRError;
export declare class DynamicServerError extends Error {
  readonly digest = "DYNAMIC_SERVER_USAGE";
  readonly description: string;
  constructor(description: string);
}
export declare function isDynamicServerError(error: unknown): error is DynamicServerError;
/**
 * Rethrow framework control-flow signals before user error handling consumes
 * them. This covers the categories vinext can currently produce.
 */
export declare function unstable_rethrow(error: unknown): void;
//#endregion